mapper.select:
SELECT (select b.grid_name from bm_grid b where b.delete_flag = 0 and b.grid_code=a.parent_code and b.tenant_id = a.tenant_id and b.industry_code = a.industry_code) as parent_name, a.grid_id, a.is_end, a.grid_code, a.grid_name, a.parent_id, a.parent_code, a.grid_level, a.create_time, a.point_status, a.color, a.grid_center, a.grid_range, a.border_color, a.border_color_transparency, a.border_color_line_thickness, a.color_transparency, a.province_id as provinceCode, a.city_id as cityCode, a.province_name, a.city_name FROM bm_grid a WHERE a.delete_flag = 0
and a.grid_level_code like concat('%',#{gridLevelCode},'%')
and a.grid_id = #{gridId}
and a.parent_id = #{parentId}
and a.grid_id != #{excludeGridId}
and a.province_id = #{provinceId}
and a.city_id = #{cityId}
AND (a.province_id, a.city_id) IN
(#{item.provinceId}, #{item.cityId})
${dataScope}
order by a.grid_sort

SELECT a.tenant_id,a.grid_id,a.grid_name, a.color,a.grid_range,a.grid_level,a.grid_center,a.industry_code FROM bm_grid a WHERE a.delete_flag = 0 AND a.point_status='1' AND a.tenant_id IN
#{item}
${dataScope}
ORDER BY a.grid_level desc

