update vm_device_info_t
set province_id = #{item.provinceCode}
, city_id = #{item.cityCode}
, county_id = #{item.countyCode}
, town_code = #{item.townCode}
where longitude = #{item.longitude}
and latitude = #{item.latitude};
update bm_gridkeeper
set province_id = #{item.provinceCode}
, city_id = #{item.cityCode}
, county_id = #{item.countyCode}
where longitude = #{item.longitude}
and latitude = #{item.latitude}

